package com.hostel.hostelmanagement.controller; import com.hostel.hostelmanagement.dto.*; import com.hostel.hostelmanagement.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController {final AuthService s;public AuthController(AuthService s){this.s=s;}@PostMapping("/register") ResponseEntity<?> register(@Valid @RequestBody RegisterRequest r){try{return ResponseEntity.status(201).body(s.register(r));}catch(Exception e){return ResponseEntity.badRequest().body(java.util.Map.of("message",e.getMessage()));}}@PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody LoginRequest r){try{return ResponseEntity.ok(s.login(r));}catch(Exception e){return ResponseEntity.status(401).body(java.util.Map.of("message",e.getMessage()));}}}